n.exploreUrl:
@js:
sort=[];
burl=source.getKey();
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

  fl_url = burl + "/JunJiProject/app/bk/001";
  fl_data = JSON.parse(java.ajax(fl_url)).data;

  fl_data.map(($,index)=>{	   	   	 
  	name = $.name;
  	if(name=="环球时报"){
  url = `/JunJiProject/JUNJI_012_001/getSearchList?keyword=${name}&pageIndex=1&pagesize=20&bkpagesize=10`;
  }else{
	      	url = `/JunJiProject/app/bk/003?cateId=${$.cateId}&page={{page}}&pagesize=20`;}
	        if(index+1 <= fl_data.length - fl_data.length%3)
			 {	push(name, url, 1, 0.25);}
				else{ push(name, url, 0, 0.29);}
        });

JSON.stringify(sort);

